#!/usr/bin/env bash
# =============================================================================
# PEIT Test & Workspace Cleanup Script (util/clean.sh)
#
# Removes temporary artifacts generated by test runs, Python caches,
# temporary databases, LaTeX build files, and mobile test build caches.
# =============================================================================

set -euo pipefail

readonly SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
readonly PROJECT_ROOT="$(cd -- "${SCRIPT_DIR}/.." && pwd)"

# Color codes
if [[ -t 1 ]] && [[ -z "${NO_COLOR:-}" ]]; then
    readonly C_RESET='\033[0m'
    readonly C_BOLD='\033[1m'
    readonly C_GREEN='\033[32m'
    readonly C_CYAN='\033[36m'
else
    readonly C_RESET=""
    readonly C_BOLD=""
    readonly C_GREEN=""
    readonly C_CYAN=""
fi

log_info() {
    printf "${C_CYAN}[CLEAN]${C_RESET} %s\n" "$*"
}

log_done() {
    printf "${C_GREEN}[DONE]${C_RESET} %s\n" "$*"
}

cd "$PROJECT_ROOT"

log_info "Cleaning Python bytecode, pycache, and pytest caches..."
find . -type d -name "__pycache__" -exec rm -rf {} + 2>/dev/null || true
find . -type d -name ".pytest_cache" -exec rm -rf {} + 2>/dev/null || true
find . -type f -name "*.pyc" -delete 2>/dev/null || true
find . -type f -name "*.pyo" -delete 2>/dev/null || true
find . -type f -name "*.pyd" -delete 2>/dev/null || true

log_info "Cleaning ephemeral test ledgers, databases, and WAL/journal files..."
rm -f web_test_ledger.jsonl 2>/dev/null || true
rm -f .peit_paired_devices.json 2>/dev/null || true
rm -f data/.peit_paired_devices.json 2>/dev/null || true
find . -type f -name "*.db-journal" -delete 2>/dev/null || true
find . -type f -name "*.db-wal" -delete 2>/dev/null || true
find . -type f -name "*.db-shm" -delete 2>/dev/null || true

log_info "Cleaning coverage reports and temporary run logs..."
rm -rf htmlcov/ .coverage .coverage.* 2>/dev/null || true

log_info "Cleaning LaTeX intermediate compilation artifacts..."
rm -f doc/showcase/*.aux doc/showcase/*.log doc/showcase/*.out doc/showcase/*.toc doc/showcase/*.fls doc/showcase/*.fdb_latexmk 2>/dev/null || true

log_info "Cleaning Dart / Flutter temporary build & lock files..."
rm -rf mobile/build/ 2>/dev/null || true
rm -rf mobile/.dart_tool/ 2>/dev/null || true
rm -f mobile/.flutter-plugins 2>/dev/null || true
rm -f mobile/.flutter-plugins-dependencies 2>/dev/null || true

log_done "All test run artifacts, caches, and temporary files cleaned successfully."

